import * as T from './vendor/three.js';
const cache={};
function softTexture(fire){const key=fire?'fire':'mist';if(cache[key])return cache[key];const w=64,h=128,a=new Uint8Array(w*h*4);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const u=x/w*2-1,v=y/h;const taper=fire?(.2+.8*(1-v)):1;const r=Math.sqrt((u/taper)**2+((v-.4)*1.5)**2);const alpha=Math.max(0,1-r);const i=(y*w+x)*4;a[i]=255;a[i+1]=fire?Math.round(90+160*(1-v)):255;a[i+2]=fire?Math.round(15+190*(1-v)**3):255;a[i+3]=Math.round(alpha*alpha*210)}const t=new T.DataTexture(a,w,h);t.needsUpdate=true;cache[key]=t;return t}
export function buildEffect(kind){const root=new T.Group(),sprites=[];const fire=kind==='fire';for(let j=0;j<(fire?70:28);j++){const material=new T.SpriteMaterial({map:softTexture(fire),color:fire?'#ffb343':'#e6edf0',transparent:true,opacity:.4,depthWrite:false,blending:fire?T.AdditiveBlending:T.NormalBlending});const s=new T.Sprite(material);root.add(s);sprites.push(s)}return {root,update(p){const active=effectEnvelope(p)>.001;root.visible=active;sprites.forEach((s,j)=>{const q=(p*(fire?7:2.5)+j/sprites.length)%1;const x=(j%7-3)*.63;const drift=Math.sin(j*2.4+q*4)*.12;s.position.set(x+drift,fire?1+q*.85:1.4+q*1.7,fire?.63:(j%3-1)*.18);s.scale.set(fire?.18+(1-q)*.23:.25+q*.65,fire?.3+q*.75:.3+q*.8,1);s.material.opacity=(fire?.65:.2)*Math.sin(q*Math.PI)*effectEnvelope(p);s.material.rotation=fire?drift*.4:drift})}}}

export function effectEnvelope(p){const smooth=x=>{const q=Math.max(0,Math.min(1,x));return q*q*(3-2*q)};return smooth(p/.18)*(1-smooth((p-.82)/.18))}
export function buildAtmosphere(kind){
 const root=new T.Group();root.name=kind+'-atmosphere';const heat=kind==='heat';const color=heat?'#ee5138':'#56b8f2',sprites=[],streams=[];
 for(let j=0;j<(heat?18:12);j++){const material=new T.SpriteMaterial({map:softTexture(false),color,transparent:true,opacity:0,depthWrite:false,blending:T.NormalBlending});const s=new T.Sprite(material);root.add(s);sprites.push(s)}
 if(!heat)for(let j=0;j<10;j++){const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(new Float32Array(18*3),3));const line=new T.Line(geometry,new T.LineBasicMaterial({color:'#76caff',transparent:true,opacity:.5,depthWrite:false}));root.add(line);streams.push(line)}
 const light=new T.PointLight(color,0,6);light.position.set(0,1.6,0);root.add(light);
 return {root,update(p){const envelope=effectEnvelope(p);root.visible=envelope>.001;light.intensity=envelope*(heat?2:1.2);sprites.forEach((s,j)=>{const q=(p*(heat?2:3)+j/sprites.length)%1;s.position.set(heat?(j%6-2.5)*.8:-2.6+q*5.2,heat?1.15+q*1.8:1.3+(j%3)*.3+(kind==='drying'?q*.4:0),Math.sin(j*2.2+q*3)*.48);s.scale.set(heat?1.6:1.3,heat?1.9:.65,1);s.material.opacity=envelope*Math.sin(q*Math.PI)*(heat?.095:.12)});streams.forEach((line,j)=>{const q=(p*2.4+j/10)%1,arr=line.geometry.attributes.position;for(let k=0;k<18;k++){const t=k/17,x=-2.7+q*5.4-t*.85;arr.setXYZ(k,x,1.25+(j%3)*.33+Math.sin(x*1.7+j)*.08+(kind==='drying'?(x+2.7)*.055:0),(j%2?-.45:.45)+Math.sin(x+j)*.09)}arr.needsUpdate=true;line.geometry.computeBoundingSphere();line.material.opacity=envelope*.5})}}
}
